import contextlib
import io
import unittest

from textkit import near
from textkit.cli import main


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class LevenshteinTest(unittest.TestCase):
    def test_known_distance(self):
        self.assertEqual(near.levenshtein("kitten", "sitting"), 3)

    def test_empty_strings(self):
        self.assertEqual(near.levenshtein("", ""), 0)
        self.assertEqual(near.levenshtein("", "abc"), 3)
        self.assertEqual(near.levenshtein("abc", ""), 3)

    def test_identical_is_zero(self):
        self.assertEqual(near.levenshtein("hello", "hello"), 0)

    def test_single_insert_delete_substitute(self):
        self.assertEqual(near.levenshtein("helo", "hello"), 1)
        self.assertEqual(near.levenshtein("hello", "helo"), 1)
        self.assertEqual(near.levenshtein("cat", "cut"), 1)

    def test_symmetric(self):
        self.assertEqual(near.levenshtein("flaw", "lawn"), near.levenshtein("lawn", "flaw"))


class ClosestTest(unittest.TestCase):
    def test_picks_nearest(self):
        self.assertEqual(near.closest("helo", ["help", "hello", "world"]), "hello")

    def test_within_max_distance(self):
        self.assertEqual(near.closest("helo", ["world", "hell"], max_distance=1), "hell")

    def test_beyond_max_distance_is_none(self):
        self.assertIsNone(near.closest("zzzz", ["hello"]))
        self.assertIsNone(near.closest("helo", ["hello"], max_distance=0))

    def test_exact_match_at_zero(self):
        self.assertEqual(near.closest("hello", ["help", "hello"], max_distance=0), "hello")

    def test_ties_go_to_first(self):
        self.assertEqual(near.closest("ab", ["ac", "ad"]), "ac")
        self.assertEqual(near.closest("ab", ["ad", "ac"]), "ad")

    def test_empty_candidates_is_none(self):
        self.assertIsNone(near.closest("hello", []))

    def test_negative_max_raises(self):
        with self.assertRaises(ValueError):
            near.closest("hello", ["hello"], max_distance=-1)
        with self.assertRaises(ValueError):
            near.closest("hello", [], max_distance=-1)


